style.css:
/* Dimension C-137 — Global Alien Sunset */
/* i really want this to be global */

/* cambia i colori qui */
:root {
  --my-pink: #ff9dba;
  --my-green: #83e84d;
  --my-purple: #7864b8;
  --my-blue: #70d5df;
  --my-bg: #211d42;
  --my-text: #fff1d9;
}

/* sfondo cosmico */
body {
  background:
    radial-gradient(ellipse at 15% 20%, #785da0 0%, transparent 45%),
    radial-gradient(ellipse at 85% 75%, #287b81 0%, transparent 45%),
    linear-gradient(135deg, #211d42, #48366b, #a45f91) !important;
  color: var(--my-text) !important;
  font-family: "Trebuchet MS", sans-serif !important;
}

/* pannelli interdimensionali */
main, article, section {
  border-radius: 18px !important;
}

/* link verde portale */
a {
  color: var(--my-green) !important;
  transition: color .2s ease !important;
}

a:hover {
  color: var(--my-pink) !important;
}

/* immagini morbide */
img {
  border-radius: 12px !important;
}

/* selezione rosa alieno */
::selection {
  background: var(--my-green) !important;
  color: #211d42 !important;
}
